unsigned long long adler32(unsigned long long adler, char* buf, int len) {

	unsigned long long sum2 = (adler >> 16) & 0xffff;

	adler &= 0xffff;

	if (len == 1) {

		adler += buf[0];

		if (adler >= 65521) adler -= 65521;

		sum2 += adler;

		if (sum2 >= 65521) sum2 -= 65521;

		return adler | (sum2 << 16);

	}

	if (buf == NULL) return 1L;

	if (len < 16) {

		while (len--) {

			adler += *buf++;

			sum2 += adler;

		}

		if (adler >= 65521) adler -= 65521;

		if (sum2 >= 65521) sum2 -= 65521;

		return adler | (sum2 << 16);

	}

	while (len >= 5552) {

		len -= 5552;

		int n = 5552 / 16;

		do {

			adler += buf[0]; adler += buf[1]; adler += buf[2]; adler += buf[3];

			adler += buf[4]; adler += buf[5]; adler += buf[6]; adler += buf[7];

			adler += buf[8]; adler += buf[9]; adler += buf[10]; adler += buf[11];

			adler += buf[12]; adler += buf[13]; adler += buf[14]; adler += buf[15];

			buf += 16;

		} while (--n);

		if (adler >= 65521) adler -= 65521;

		sum2 += adler;

		if (sum2 >= 65521) sum2 -= 65521;

	}

	if (len) {

		while (len >= 16) {

			len -= 16;

			adler += buf[0]; adler += buf[1]; adler += buf[2]; adler += buf[3];

			adler += buf[4]; adler += buf[5]; adler += buf[6]; adler += buf[7];

			adler += buf[8]; adler += buf[9]; adler += buf[10]; adler += buf[11];

			adler += buf[12]; adler += buf[13]; adler += buf[14]; adler += buf[15];

			buf += 16;

		}

		while (len--) {

			adler += *buf++;

			sum2 += adler;

		}

		if (adler >= 65521) adler -= 65521;

		if (sum2 >= 65521) sum2 -= 65521;

	}

	return adler | (sum2 << 16);

}

int main() {

	scanf("%d%d%llu", &n, &k, &seed);

	for (int i = 0; i < n; i++) s[i] = (seed >> 32) & 0xff;

	ans = 1;

	for (int i = 0; i < k; i++) {

		ans = adler32(ans, s + (i % 64), n > 64 ? n - (i % 61) : n);

		seed = seed * 1103515245 + 12345;

	}

	printf("%llu\n", ans);

	return 0;

}

