using namespace std;

const int N = 1e5 + 10;

char s[N];

int n, k;

unsigned long long seed;

unsigned long long rng() {

	seed ^= seed << 13;

	seed ^= seed >> 7;

	seed ^= seed << 17;

	return seed;

}

int main() {

	scanf("%d%d%llu", &n, &k, &seed);

	for (int i = 0; i < n; i++) s[i] = rng() % 256;

	int ans = 0;

	for (int i = 0; i < k; i++) {

		int x = rng() % n;

		int y = rng() % n;

		if (x > y) swap(x, y);

		unsigned long long h = 0;

		for (int j = x; j <= y; j++) h = h * 31 + s[j];

		ans = ans * 31 + h;

	}

	printf("%d\n", ans);

	return 0;

}

