using namespace std;

typedef long long ll;

const int maxn = 1e5 + 5;

int n, q;

ll a[maxn];

ll bit[maxn];

void add(int x, ll v) {

    for (; x <= n; x += x & -x) {

        bit[x] += v;

    }

}

ll query(int x) {

    ll res = 0;

    for (; x > 0; x -= x & -x) {

        res += bit[x];

    }

    return res;

}

