    scanf("%d%d", &n, &q);

    for (int i = 1; i <= n; i++) {

        scanf("%lld", &a[i]);

        add(i, a[i]);

    }

    while (q--) {

        int op, x, y;

        scanf("%d%d%d", &op, &x, &y);

        if (op == 0) {

            add(x, y);

        } else {

            printf("%lld\n", query(y) - query(x - 1));

        }

    }

    return 0;

}

