using namespace std;

char s[100005];

int n, sa[100005], rk[100005], height[100005];

int c[100005];

void get_SA()

{

    int *x = sa, *y = c, i, j, p;

    for (i = 0; i < n; i++)

        y[++x[s[i]]] = i;

    for (i = 1; i < n; i++)

        x[i] += x[i - 1];

    for (i = n - 1; i >= 0; i--)

        sa[--x[y[i]]] = y[i];

    for (p = 1; p < n; p <<= 1)

    {

        for (i = n - p; i < n; i++)

            y[++x[rk[i]]] = i;

        for (i = 0; i < n; i++)

            if (sa[i] >= p)

                y[++x[rk[sa[i] - p]]] = sa[i] - p;

        for (i = 1; i < n; i++)

            x[i] += x[i - 1];

        for (i = n - 1; i >= 0; i--)

            sa[--x[y[i]]] = y[i];

        swap(rk, y);

        rk[sa[0]] = 0;

        for (i = 1; i < n; i++)

            rk[sa[i]] = y[sa[i]] == y[sa[i - 1]] && y[sa[i] + p] == y[sa[i - 1] + p] ? rk[sa[i - 1]] : i;

        if (rk[sa[n - 1]] == n - 1)

            break;

    }

}

void get_height()

{

    int i, j, k = 0;

    for (i = 0; i < n; i++)

        rk[sa[i]] = i;

    for (i = 0; i < n; i++)

    {

        if (k)

            k--;

        j = sa[rk[i] - 1];

        while (s[i + k] == s[j + k])

            k++;

        height[rk[i]] = k;

    }

}

int main()

{

    scanf("%s", s);

    n = strlen(s);

    for (int i = 0; i < n; i++)

        sa[i] = i, rk[i] = s[i];

    get_SA();

    get_height();

    long long ans = 0;

    for (int i = 1; i < n; i++)

        ans += n - sa[i] - height[i];

    printf("%lld\n", ans);

    return 0;

}

