typedef long long ll;

ll n, m, a, b;

ll f(ll x) {

    return x * (x + 1) / 2;

}

ll g(ll x) {

    return x * (x + 1) / 2 % m;

}

ll h(ll x) {

    return x * (x + 1) / 2 / m;

}

ll calc(ll n, ll m, ll a, ll b) {

    ll ans = 0;

    if (a >= m) {

        ans += n * (n - 1) / 2 * (a / m);

        a %= m;

    }

    if (b >= m) {

        ans += n * (b / m);

        b %= m;

    }

    ll y = a * n + b;

    if (y < m) return ans;

    ll x = n;

    n = (y / m);

    b = (y % m);

    swap(m, a);

    ans += f(x) - f(x - n) + g(x) - g(x - n) - h(x) + h(x - n);

    return ans;

}

