	memset(level, -1, sizeof(level));

	queue<int> q;

	q.push(s);

	level[s] = 0;

	while (!q.empty()) {

		int u = q.front();

		q.pop();

		for (int i = head[u]; i; i = e[i].next) {

			if (e[i].flow < e[i].cap && level[e[i].v] == -1) {

				level[e[i].v] = level[u] + 1;

				q.push(e[i].v);

			}

		}

	}

	return level[t] != -1;

}

