unsigned hash(char *s, unsigned len, unsigned seed) {
	unsigned m = 0xc6a4a793;
	unsigned r = 24;
	unsigned h = seed ^ (len * m);

	while (len >= 4) {
		h += *(unsigned *)s;
		s += 4;
		len -= 4;

		h *= m;
		h ^= h >> 16;
	}

	switch (len) {
	case 3: h += s[2] << 16;
	case 2: h += s[1] << 8;
	case 1: h += s[0];
		h *= m;
		h ^= h >> r;
	}

	return h;
}

