#include <cstdio>
#include <cstring>

int min(int a, int b) {
    return a < b ? a : b;
}

int main() {
    int q;
    scanf("%d", &q);
    while (q--) {
        char a[100001], b[100001];
        scanf("%s%s", a, b);
        int n = strlen(a), m = strlen(b);
        int dp[n+1][m+1];
        memset(dp, 0, sizeof(dp));
        for (int i = 0; i <= n; i++) dp[i][0] = i;
        for (int j = 0; j <= m; j++) dp[0][j] = j;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (a[i-1] == b[j-1]) dp[i][j] = dp[i-1][j-1];
                else dp[i][j] = min(min(dp[i-1][j]+3, dp[i][j-1]+1), dp[i-1][j-1]+2);
            }
        }
        printf("%d\n", dp[n][m]);
    }
    return 0;
}

