unsigned int murmurhash(const char* key, int len) {
	unsigned int seed = 0;
	const int m = 0x5bd1e995;
	const int r = 24;
	unsigned int h = seed ^ len;
	while(len >= 4) {
		unsigned int k = *(unsigned int*)key;
		k *= m;
		k ^= k >> r;
		k *= m;
		h *= m;
		h ^= k;
		key += 4;
		len -= 4;
	}
	switch(len) {
	case 3: h ^= key[2] << 16;
	case 2: h ^= key[1] << 8;
	case 1: h ^= key[0];
			h *= m;
	}
	h ^= h >> 13;
	h *= m;
	h ^= h >> 15;
	return h;
}

char s[100000];

int main() {
	int q;
	scanf("%d", &q);
	while(q--) {
		scanf("%s", s);
		printf("%u\n", murmurhash(s, strlen(s)));
	}
	return 0;
}

