#define MAXN 1 << 16

char p[MAXN], s[MAXN];

int main() {
  int q; scanf("%d", &q);
  for (int i = 0; i < q; i++) {
    int nocase; scanf("%s %s %d", p, s, &nocase);
    int plen = strlen(p), slen = strlen(s);
    int pi = 0, si = 0;
    while (pi < plen && si < slen) {
      if (p[pi] == '*') {
        while (pi < plen && p[pi] == '*') pi++;
        if (pi == plen) break;
        while (si < slen && (nocase ? tolower(p[pi]) : p[pi]) != (nocase ? tolower(s[si]) : s[si])) si++;
      } else if (p[pi] == '?') {
        pi++; si++;
      } else if (p[pi] == '[') {
        pi++;
        int neg = 0;
        if (p[pi] == '^') {
          neg = 1;
          pi++;
        }
        int match = 0;
        while (pi < plen && p[pi] != ']') {
          if (p[pi] == '\\' && pi + 1 < plen) {
            pi++;
            if ((nocase ? tolower(p[pi]) : p[pi]) == (nocase ? tolower(s[si]) : s[si])) match = 1;
          } else if (pi + 2 < plen && p[pi + 1] == '-' && p[pi + 2] != ']') {
            int start = (nocase ? tolower(p[pi]) : p[pi]);
            int end = (nocase ? tolower(p[pi + 2]) : p[pi + 2]);
            int c = (nocase ? tolower(s[si]) : s[si]);
            if (start > end) std::swap(start, end);
            if (c >= start && c <= end) match = 1;
            pi += 2;
          } else {
            if ((nocase ? tolower(p[pi]) : p[pi]) == (nocase ? tolower(s[si]) : s[si])) match = 1;
          }
          pi++;
        }
        if (neg) match = !match;
        if (!match) goto fail;
        si++;
      } else if (p[pi] == '\\') {
        pi++;
        if (pi == plen || (nocase ? tolower(p[pi]) : p[pi]) != (nocase ? tolower(s[si]) : s[si])) goto fail;
        pi++; si++;
      } else {
        if ((nocase ? tolower(p[pi]) : p[pi]) != (nocase ? tolower(s[si]) : s[si])) goto fail;
        pi++; si++;
      }
    }
    while (pi < plen && p[pi] == '*') pi++;
    if (pi == plen && si == slen) puts("1");
    else fail: puts("0");
  }
  return 0;
}

