inline bool match(char a, char b, int nocase) {
  if (nocase) a = tolower(a), b = tolower(b);
  return a == b;
}

bool stringmatchlen(const char *p, int plen, const char *s, int slen, int nocase) {
  for (int i = 0; i < plen; i++) {
    if (p[i] == '*') {
      for (int j = 0; j <= slen - (plen - i); j++) {
        if (stringmatchlen(p + i + 1, plen - i - 1, s + j, slen - j, nocase)) return true;
      }
      return false;
    } else if (p[i] == '?') {
      if (i == plen - 1) return true;
      continue;
    } else if (p[i] == '[') {
      int j = i + 1;
      bool neg = false;
      if (p[j] == '^') neg = true, j++;
      bool match = false;
      while (p[j] != ']') {
        if (p[j] == '\\' && j + 1 < plen) j++;
        if (match) break;
        if (j + 2 < plen && p[j + 1] == '-' && p[j + 2] != ']') {
          if (match = match(s[i], p[j], nocase) || match(s[i], p[j + 2], nocase)) break;
          j += 3;
        } else {
          if (match = match(s[i], p[j], nocase)) break;
          j++;
        }
      }
      if (neg) match = !match;
      if (!match) return false;
      i = j;
    } else if (p[i] == '\\') {
      if (i + 1 < plen && !match(s[i], p[i + 1], nocase)) return false;
      i++;
    } else {
      if (!match(s[i], p[i], nocase)) return false;
    }
  }
  return true;
}

int main() {
  int q; scanf("%d", &q);
  for (int i = 0; i < q; i++) {
    scanf("%s %s", p, s);
    int nocase; scanf("%d", &nocase);
    puts(stringmatchlen(p, strlen(p), s, strlen(s), nocase) ? "Yes" : "No");
  }
  return 0;
}

#include <cctype>
