#include <cstring>

static inline int stringmatchlen(const char* pattern, int pattern_len, const char* str, int str_len, int nocase) {
  while (pattern_len && str_len) {
    switch (pattern[0]) {
      case '*': {
        while (pattern_len && pattern[1] == '*') {
          ++pattern;
          --pattern_len;
        }
        if (pattern_len == 1) return 1;
        while (str_len) {
          if (stringmatchlen(pattern + 1, pattern_len - 1, str, str_len, nocase)) return 1;
          ++str;
          --str_len;
        }
        return 0;
      }
      case '?':
        ++str;
        --str_len;
        break;
      case '[': {
        int negate, match;

        ++pattern;
        --pattern_len;
        negate = pattern_len && pattern[0] == '^';
        if (negate) {
          ++pattern;
          --pattern_len;
        }
        match = 0;
        while (1) {
          if (pattern_len >= 2 && pattern[0] == '\\') {
            ++pattern;
            --pattern_len;
            if (pattern[0] == str[0]) match = 1;
          } else if (pattern_len == 0) {
            --pattern;
            ++pattern_len;
            break;
          } else if (pattern[0] == ']') {
            break;
          } else if (pattern_len >= 3 && pattern[1] == '-') {
            int start = pattern[0];
            int end = pattern[2];
            int c = str[0];
            if (start > end) {
              int t = start;
              start = end;
              end = t;
            }
            if (nocase) {
              start = std::tolower(start);
              end = std::tolower(end);
              c = std::tolower(c);
            }
            pattern += 2;
            pattern_len -= 2;
            if (c >= start && c <= end) match = 1;
          } else {
            if (!nocase) {
              if (pattern[0] == str[0]) match = 1;
            } else {
              if (std::tolower(static_cast<int>(pattern[0])) ==
                  std::tolower(static_cast<int>(str[0])))
                match = 1;
            }
          }
          ++pattern;
          --pattern_len;
        }
        if (negate) match = !match;
        if (!match) return 0;
        ++str;
        --str_len;
        break;
      }
      case '\\':
        if (pattern_len >= 2) {
          ++pattern;
          --pattern_len;
        }
        // fallthrough
      default:
        if (!nocase) {
          if (pattern[0] != str[0]) return 0;
        } else {
          if (std::tolower(static_cast<int>(pattern[0])) !=
              std::tolower(static_cast<int>(str[0]))) return 0;
        }
        ++str;
        --str_len;
        break;
    }
    ++pattern;
    --pattern_len;
    if (str_len == 0) {
      while (pattern_len && *pattern == '*') {
        ++pattern;
        --pattern_len;
      }
      break;
    }
  }
  if (pattern_len == 0 && str_len == 0) return 1;
  return 0;
}

int main() {
  int q; scanf("%d", &q);
  static char p[1 << 16], s[1 << 16];
  for (int i = 0; i < q; i++) {
    int nocase;
    scanf("%s %s %d", p, s, &nocase);
    puts(stringmatchlen(p, strlen(p), s, strlen(s), nocase) ? "YES" : "NO");
  }
  return 0;
}

