const int MAXN = 1e5 + 10;

int n, k;
unsigned long long seed;
char buf[MAXN];

inline void init() {
	scanf("%d%d%llu", &n, &k, &seed);
	for (int i = 0; i < n; ++i) buf[i] = rand();
}

inline unsigned long long adler32(unsigned long long adler, const char* buf, int len) {
	unsigned long long sum2 = (adler >> 16) & 0xffff;
	adler &= 0xffff;
	while (len--) {
		adler += *buf++;
		sum2 += adler;
		if (adler >= 65521) adler -= 65521;
		if (sum2 >= 65521) sum2 -= 65521;
	}
	return (adler << 16) | sum2;
}

int main() {
	init();
	unsigned long long ans = 1;
	for (int i = 0; i < k; ++i) ans = adler32(ans, buf + (i % 64), n > 64 ? n - (i % 61) : n);
	printf("%llu\n", ans);
	return 0;
}

