template<typename T>
T pow(T a, ll n) {
  T res = 1;
  while (n > 0) {
    if (n & 1) res *= a;
    a *= a;
    n >>= 1;
  }
  return res;
}

template<typename T>
T pow(T a, ll n, T mod) {
  T res = 1;
  while (n > 0) {
    if (n & 1) res = res * a % mod;
    a = a * a % mod;
    n >>= 1;
  }
  return res;
}

template<typename T>
T inv(T a, T mod) {return pow(a, mod-2, mod);}

template<typename T>
T extgcd(T a, T b, T& x, T& y) {
  if (b == 0) {
    x = 1;
    y = 0;
    return a;
  }
  T d = extgcd(b, a % b, y, x);
  y -= a / b * x;
  return d;
}

template<typename T>
T modinv(T a, T mod) {
  T x, y;
  extgcd(a, mod, x, y);
  return (x % mod + mod) % mod;
}

