#define ALLOC_ARRAY(x, alloc) (x) = (int*) malloc(sizeof(*x) * (alloc))

int levenshtein(const char* str1, const char* str2, int w, int s, int a, int d) {
    int len1 = strlen(str1), len2 = strlen(str2);
    int* row0, * row1, * row2;
    int i, j;

    ALLOC_ARRAY(row0, len2 + 1);
    ALLOC_ARRAY(row1, len2 + 1);
    ALLOC_ARRAY(row2, len2 + 1);

    for (j = 0; j <= len2; j++)
        row1[j] = j * a;

    for (i = 0; i < len1; i++) {
        int* dummy;
        row2[0] = (i + 1) * d;
        for (j = 0; j < len2; j++) {
            /* substitution */
            row2[j + 1] = row1[j] + s * (str1[i] != str2[j]);

            /* swap */
            if (i > 0 && j > 0 && str1[i - 1] == str2[j] && str1[i] == str2[j - 1] && row2[j + 1] > row0[j - 1] + w)
                row2[j + 1] = row0[j - 1] + w;

            /* deletion */
            if (row2[j + 1] > row1[j + 1] + d)
                row2[j + 1] = row1[j + 1] + d;

            /* insertion */
            if (row2[j + 1] > row2[j] + a)
                row2[j + 1] = row2[j] + a;
        }

        dummy = row0;
        row0 = row1;
        row1 = row2;
        row2 = dummy;
    }

    i = row1[len2];

    free(row0);
    free(row1);
    free(row2);

    return i;
}

static uint64_t st;

static inline uint64_t rnd() {
    st ^= st << 13;
    st ^= st >> 7;
    st ^= st << 17;
    return st;
}

int main() {
    int m, len;
    unsigned long long seed;

    scanf("%d %d %llu", &m, &len, &seed);

    st = seed | 1;

    std::vector<std::string> words(m);

    for (auto& w : words) {
        w.resize(len / 2 + rnd() % len);
        for (auto& c : w) c = 'a' + rnd() % 6;
    }

    long long total = 0;

    for (int i = 0; i + 1 < m; i++)
        total += levenshtein(words[i].c_str(), words[i + 1].c_str(), 0, 2, 1, 3);

    printf("%lld\n", total);

    return 0;
}

