#include <stdint.h>

#define MAXN 1000

int n, l;
unsigned long long seed;

char str[MAXN][MAXN];

int dp[MAXN][MAXN];

int min(int a, int b) {
    return a < b ? a : b;
}

int main() {
    scanf("%d%d%llu", &n, &l, &seed);

    for (int i = 0; i < n; i++) {
        int len = l / 2 + rand() % l;
        for (int j = 0; j < len; j++) {
            str[i][j] = 'a' + rand() % 6;
        }
        str[i][len] = '\0';
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            dp[i][j] = 0;
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int len1 = strlen(str[i]);
            int len2 = strlen(str[j]);
            for (int k = 0; k <= len1; k++) {
                dp[i][j] += k;
            }
            for (int k = 0; k <= len2; k++) {
                dp[i][j] += k;
            }
            for (int k = 0; k < len1 && k < len2; k++) {
                if (str[i][k] != str[j][k]) {
                    dp[i][j] += 2;
                }
            }
        }
    }

    int ans = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            ans += dp[i][j];
        }
    }

    printf("%d\n", ans);

    return 0;
}

