typedef unsigned long long ull;

ull rands[1000000];

inline ull rand() {
	static ull x = 123456789, y = 362436069, z = 521288629, w = 88675123;
	ull t = x ^ (x << 11);
	x = y; y = z; z = w;
	return w = w ^ (w >> 19) ^ (t ^ (t >> 8));
}

inline void init(int n, ull seed) {
	rands[0] = seed | 1;
	for (int i = 1; i <= n; i++) rands[i] = rand();
}

inline ull siphash(const char* in, int len, const char* key) {
	ull v0 = 0x736f6d6570736575ULL;
	ull v1 = 0x646f72616e646f6dULL;
	ull v2 = 0x6c7967656e657261ULL;
	ull v3 = 0x7465646279746573ULL;
	ull k0 = *(ull*)key;
	ull k1 = *(ull*)(key + 8);
	ull m;
	const char* end = in + len - (len % 8);
	const int left = len & 7;
	ull b = ((ull)len) << 56;
	v3 ^= k1;
	v2 ^= k0;
	v1 ^= k1;
	v0 ^= k0;

	for (; in != end; in += 8) {
		m = *(ull*)in;
		v3 ^= m;

		//SIPROUND
		v0 += v1; v1 = __builtin_rotateleft64(v1, 13); v1 ^= v0; v0 = __builtin_rotateleft64(v0, 32);
		v2 += v3; v3 = __builtin_rotateleft64(v3, 16); v3 ^= v2; v2 = __builtin_rotateleft64(v2, 32);
		v0 += v3; v3 = __builtin_rotateleft64(v3, 21); v3 ^= v0;
		v2 += v1; v1 = __builtin_rotateleft64(v1, 17); v1 ^= v2; v2 = __builtin_rotateleft64(v2, 32);

		v0 ^= m;
	}

	switch (left) {
	case 7: b |= ((ull)in[6]) << 48; // fall-thru
	case 6: b |= ((ull)in[5]) << 40; // fall-thru
	case 5: b |= ((ull)in[4]) << 32; // fall-thru
	case 4: b |= ((ull)in[3]) << 24; // fall-thru
	case 3: b |= ((ull)in[2]) << 16; // fall-thru
	case 2: b |= ((ull)in[1]) << 8; // fall-thru
	case 1: b |= ((ull)in[0]); break;
	case 0: break;
	}

	v3 ^= b;

	//SIPROUND
	v0 += v1; v1 = __builtin_rotateleft64(v1, 13); v1 ^= v0; v0 = __builtin_rotateleft64(v0, 32);
	v2 += v3; v3 = __builtin_rotateleft64(v3, 16); v3 ^= v2; v2 = __builtin_rotateleft64(v2, 32);
	v0 += v3; v3 = __builtin_rotateleft64(v3, 21); v3 ^= v0;
	v2 += v1; v1 = __builtin_rotateleft64(v1, 17); v1 ^= v2; v2 = __builtin_rotateleft64(v2, 32);

	v0 ^= b;
	v2 ^= 0xff;

	//SIPROUND
	v0 += v1; v1 = __builtin_rotateleft64(v1, 13); v1 ^= v0; v0 = __builtin_rotateleft64(v0, 32);
	v2 += v3; v3 = __builtin_rotateleft64(v3, 16); v3 ^= v2; v2 = __builtin_rotateleft64(v2, 32);
	v0 += v3; v3 = __builtin_rotateleft64(v3, 21); v3 ^= v0;
	v2 += v1; v1 = __builtin_rotateleft64(v1, 17); v1 ^= v2; v2 = __builtin_rotateleft64(v2, 32);

	SIPROUND;

	b = v0 ^ v1 ^ v2 ^ v3;
	return b;
}

int main() {
	int n, k;
	ull seed;
	scanf("%d%d%llu", &n, &k, &seed);
	init(n, seed);
	char buf[1000000], key[16];
	for (int i = 0; i < n; i++) buf[i] = rands[i + 1];
	for (int i = 0; i < 16; i++) key[i] = rands[i + n + 1];
	ull ans = 0;
	for (int i = 0; i < k; i++) {
		key[i % 16] ^= i;
		ans = ans * 31 + siphash(buf + (i % 64), 1 + (i * 37) % n, key);
	}
	printf("%llu\n", ans);
	return 0;
}

