  ull b = ((ull)inlen) << 56;
  v3 ^= k1;
  v2 ^= k0;
  v1 ^= k1;
  v0 ^= k0;

  for (; in != end; in += 8) {
    m = *(ull*)in;
    v3 ^= m;

    #define SIPROUND                                                             \
      do {                                                                       \
        v0 += v1;                                                                \
        v1 = __builtin_rotateleft64(v1, 13);                                     \
        v1 ^= v0;                                                                \
        v0 = __builtin_rotateleft64(v0, 32);                                     \
        v2 += v3;                                                                \
        v3 = __builtin_rotateleft64(v3, 16);                                     \
        v3 ^= v2;                                                                \
        v0 += v3;                                                                \
        v3 = __builtin_rotateleft64(v3, 21);                                     \
        v3 ^= v0;                                                                \
        v2 += v1;                                                                \
        v1 = __builtin_rotateleft64(v1, 17);                                     \
        v1 ^= v2;                                                                \
        v2 = __builtin_rotateleft64(v2, 32);                                     \
      } while (0)

    SIPROUND;

    v0 ^= m;
  }

  switch (left) {
  case 7: b |= ((ull)in[6]) << 48; /* fall-thru */
  case 6: b |= ((ull)in[5]) << 40; /* fall-thru */
  case 5: b |= ((ull)in[4]) << 32; /* fall-thru */
  case 4: b |= ((ull)in[3]) << 24; /* fall-thru */
  case 3: b |= ((ull)in[2]) << 16; /* fall-thru */
  case 2: b |= ((ull)in[1]) << 8; /* fall-thru */
  case 1: b |= ((ull)in[0]); break;
  case 0: break;
  }

  v3 ^= b;

  SIPROUND;

  v0 ^= b;
  v2 ^= 0xff;

  SIPROUND;
  SIPROUND;

  b = v0 ^ v1 ^ v2 ^ v3;
  return b;
}

