typedef unsigned long long ull;

ull rdtsc()
{
    ull lo, hi;
    __asm__ volatile("rdtsc" : "=a"(lo), "=d"(hi));
    return (hi << 32) | lo;
}

ull rng(ull x)
{
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    return x;
}

ull siphash(const void* data, size_t len, const void* key)
{
    const char* p = (const char*)data;
    const char* end = p + len;
    ull h0 = *((ull*)key);
    ull h1 = *((ull*)((char*)key + 8));
    ull h2 = 0x6C7967656E657261;
    ull h3 = 0x7465646279746573;
    ull m;
    while (p + 8 <= end)
    {
        m = *(ull*)p;
        h3 ^= m;
        for (int i = 0; i < 2; i++)
        {
            h0 += h1;
            h1 = rotl(h1, 13);
            h1 ^= h0;
            h0 = rotl(h0, 32);
            h2 += h3;
            h3 = rotl(h3, 16);
            h3 ^= h2;
            h2 = rotl(h2, 32);
        }
        h0 += h3;
        h3 = rotl(h3, 21);
        h3 ^= h0;
        h2 += h1;
        h1 = rotl(h1, 17);
        h1 ^= h2;
        h2 = rotl(h2, 32);
        p += 8;
    }
    m = 0;
    switch (end - p)
    {
    case 7: m |= (ull)p[6] << 48; // fallthrough
    case 6: m |= (ull)p[5] << 40; // fallthrough
    case 5: m |= (ull)p[4] << 32; // fallthrough
    case 4: m |= (ull)p[3] << 24; // fallthrough
    case 3: m |= (ull)p[2] << 16; // fallthrough
    case 2: m |= (ull)p[1] << 8; // fallthrough
    case 1: m |= (ull)p[0]; break;
    case 0: break;
    }
    h3 ^= m;
    for (int i = 0; i < 2; i++)
    {
        h0 += h1;
        h1 = rotl(h1, 13);
        h1 ^= h0;
        h0 = rotl(h0, 32);
        h2 += h3;
        h3 = rotl(h3, 16);
        h3 ^= h2;
        h2 = rotl(h2, 32);
    }
    h0 += h3;
    h3 = rotl(h3, 21);
    h3 ^= h0;
    h2 += h1;
    h1 = rotl(h1, 17);
    h1 ^= h2;
    h2 = rotl(h2, 32);
    h3 ^= 0xFF;
    for (int i = 0; i < 2; i++)
    {
        h0 += h1;
        h1 = rotl(h1, 13);
        h1 ^= h0;
        h0 = rotl(h0, 32);
        h2 += h3;
        h3 = rotl(h3, 16);
        h3 ^= h2;
        h2 = rotl(h2, 32);
    }
    return h0 ^ h1 ^ h2 ^ h3;
}

