const int N = 1e5 + 10;

char pat[N], str[N];

int n, m, len;

long long ans;

bool match(int i, int j) {
    int x = 0, y = 0;
    while (x < n && y < m) {
        if (pat[x] == '*') {
            while (x < n && pat[x] == '*') x++;
            if (x == n) return true;
            while (y < m && str[y] != pat[x]) y++;
            if (y == m) return false;
        } else if (pat[x] == '?') {
            x++, y++;
        } else if (pat[x] == '[') {
            x++;
            bool flag = false;
            while (pat[x] != ']') {
                if (pat[x] == '\\' && pat[x + 1] == str[y]) {
                    flag = true;
                    break;
                } else if (pat[x] == str[y]) {
                    flag = true;
                    break;
                } else if (pat[x] == '-' && pat[x + 1] != ']') {
                    if (pat[x - 1] <= str[y] && str[y] <= pat[x + 1]) {
                        flag = true;
                        break;
                    }
                    x++;
                }
                x++;
            }
            if (!flag) return false;
            x++, y++;
        } else if (pat[x] == '\\') {
            x++;
            if (pat[x] != str[y]) return false;
            x++, y++;
        } else {
            if (pat[x] != str[y]) return false;
            x++, y++;
        }
    }
    return x == n && y == m;
}

