using namespace std;

const int N = 1e5 + 10;

char pat[N], str[N];

int n, m;

bool match(int i, int j) {
    while (pat[i] && str[j]) {
        if (pat[i] == '*') {
            while (pat[++i] == '*');
            if (!pat[i]) return true;
            while (str[j] && !match(i, j)) j++;
            return str[j];
        }
        if (pat[i] == '?') {
            i++, j++;
            continue;
        }
        if (pat[i] == '[') {
            bool flag = false;
            i++;
            while (pat[i] != ']') {
                if (pat[i] == '\\' && pat[i + 1] == str[j]) {
                    flag = true;
                    break;
                }
                if (pat[i] == str[j]) {
                    flag = true;
                    break;
                }
                if (pat[i] == '-' && pat[i - 1] <= str[j] && str[j] <= pat[i + 1]) {
                    flag = true;
                    break;
                }
                i++;
            }
            if (!flag) return false;
            i++, j++;
            continue;
        }
        if (pat[i] == '\\') {
            if (pat[i + 1] != str[j]) return false;
            i += 2, j++;
            continue;
        }
        if (pat[i] != str[j]) return false;
        i++, j++;
    }
    return !pat[i] && !str[j];
}

