  int n, q; scanf("%d %d", &n, &q);
  fenwick_tree<long long> fw(n);
  for (int i = 0; i < n; i++) { long long a; scanf("%lld", &a); fw.add(i, a); }
  for (int i = 0; i < q; i++) {
    int t; long long x, y; scanf("%d %lld %lld", &t, &x, &y);
    if (t == 0) fw.add((int)x, y); else printf("%lld\n", fw.sum((int)x, (int)y));
  }
  return 0;
}

