long long floor_sum(long long n, long long m, long long a, long long b) {
  long long ans = 0;
  if (a >= m) {
    ans += (n - 1) * n * (a / m) / 2;
    a %= m;
  }
  if (b >= m) {
    ans += n * (b / m);
    b %= m;
  }
  long long y_max = a * n + b;
  if (y_max < m) return ans;
  ans += (n - 1) * n * (y_max / m) / 2;
  y_max %= m;
  return ans + (a * n + b) / m;
}

