template<typename T>
inline T gcd(T a, T b) {
	while(b) {
		a %= b;
		swap(a, b);
	}
	return a;
}

template<typename T>
inline T lcm(T a, T b) {
	return a / gcd(a, b) * b;
}

template<typename T>
inline T powmod(T a, T b, T mod) {
	T ans = 1;
	for(; b; b >>= 1, a = a * a % mod) {
		if(b & 1) {
			ans = ans * a % mod;
		}
	}
	return ans;
}

template<typename T>
inline T inv(T a, T b) {
	T x = 1, y = 0, last_x = 0, last_y = 1;
	for(; b; a %= b, swap(a, b)) {
		T q = a / b;
		x -= q * last_x, y -= q * last_y;
		swap(x, last_x), swap(y, last_y);
	}
	return last_x;
}

template<typename T>
inline T mulmod(T a, T b, T mod) {
	T ans = 0;
	for(; b; b >>= 1, a = a * 2 % mod) {
		if(b & 1) {
			ans = (ans + a) % mod;
		}
	}
	return ans;
}

template<typename T>
inline T addmod(T a, T b, T mod) {
	return (a + b) % mod;
}

template<typename T>
inline T submod(T a, T b, T mod) {
	return (a - b + mod) % mod;
}

template<typename T>
inline T divmod(T a, T b, T mod) {
	return a * inv(b, mod) % mod;
}

template<typename T>
inline T fact(T n) {
	T ans = 1;
	for(int i = 2; i <= n; i++) {
		ans = ans * i % MOD;
	}
	return ans;
}

template<typename T>
inline T comb(T n, T m) {
	T ans = 1;
	for(int i = 0; i < m; i++) {
		ans = ans * (n - i) % MOD;
		ans = ans * inv(i + 1, MOD) % MOD;
	}
	return ans;
}

template<typename T>
inline T perm(T n, T m) {
	T ans = 1;
	for(int i = 0; i < m; i++) {
		ans = ans * (n - i) % MOD;
	}
	return ans;
}

template<typename T>
inline T catalan(T n) {
	return comb(2 * n, n) * inv(n + 1, MOD) % MOD;
}

template<typename T>
inline T lucas(T n, T m, T mod) {
	if(m == 0) {
		return 1;
	}
	return lucas(n / mod, m / mod, mod) * comb(n % mod, m % mod) % mod;
}

template<typename T>
inline T chinese_remainder(T a, T b, T c, T d) {
	T x = inv(b, d);
	return (a * d * x + c * b) % (b * d);
}

template<typename T>
inline T extended_euclid(T a, T b, T &x, T &y) {
	if(b == 0) {
		x = 1, y = 0;
		return a;
	}
	T g = extended_euclid(b, a % b, y, x);
	y -= a / b * x;
	return g;
}

template<typename T>
inline T dijkstra(vector<vector<pair<T, T>>> &g, T s, T t) {
	vector<T> dist(g.size(), INF);
	dist[s] = 0;
	priority_queue<pair<T, T>, vector<pair<T, T>>, greater<pair<T, T>>> pq;
	pq.push(mp(0, s));
	while(!pq.empty()) {
		T u = pq.top().second;
		pq.pop();
		if(u == t) {
			break;
		}
		for(auto v : g[u]) {
			if(dist[v.first] > dist[u] + v.second) {
				dist[v.first] = dist[u] + v.second;
				pq.push(mp(dist[v.first], v.first));
			}
		}
	}
	return dist[t];
}

template<typename T>
inline T floyd_warshall(vector<vector<T>> &g, T s, T t) {
	int n = g.size();
	vector<vector<T>> dist(n, vector<T>(n, INF));
	for(int i = 0; i < n; i++) {
		dist[i][i] = 0;
	}
	for(int i = 0; i < n; i++) {
		for(int j = 0; j < n; j++) {
			dist[i][j] = g[i][j];
		}
	}
	for(int k = 0; k < n; k++) {
		for(int i = 0; i < n; i++) {
			for(int j = 0; j < n; j++) {
				dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
			}
		}
	}
	return dist[s][t];
}

template<typename T>
inline T bellman_ford(vector<vector<pair<T, T>>> &g, T s, T t) {
	int n = g.size();
	vector<T> dist(n, INF);
	dist[s] = 0;
	for(int i = 0; i < n - 1; i++) {
		for(int u = 0; u < n; u++) {
			for(auto v : g[u]) {
				if(dist[v.first] > dist[u] + v.second) {
					dist[v.first] = dist[u] + v.second;
				}
			}
		}
	}
	return dist[t];
}

